// Consolida config + cobrancas + pendencias (binario -> JSON) e embute os perfis
// (mesma cópia usada na Fase 1 — seção 6 do spec.md).
function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return {};
  return JSON.parse(Buffer.from(item.binary.data.data, 'base64').toString('utf8'));
}
const config = parseBinaryJson($('Ler config_execucao.json').first());
const cobrancas = parseBinaryJson($('Ler cobrancas.json').first());
const pendencias = parseBinaryJson($('Ler pendencias_identificacao.json').first());

const perfis = {
  AREP: { projeto: 'AREP (S01 antigo)', texto_ref: 'SMTC', retranca: 'S01' },
  REUNION: { projeto: 'Reunion (S01)', texto_ref: 'SMTC - REUNION', retranca: 'REUNION_S01' },
  SOFT_PRE: { projeto: 'Soft Pré (S02)', texto_ref: 'SMTC - SOFT PRE', retranca: 'SOFT PRE_S02' },
};

return [{ json: { config, cobrancas, pendencias, perfis, dominioEmpresa: 'novorealitybox.com' } }];

// Le a aba Notas dos 2 Cost Reports (exceljs), separando AREP/Reunion por cor
// (mesma lógica da Fase 1). Produz a "roster" de nomes/razões sociais + linha,
// usada tanto pra localizar a linha de uma thread conhecida (via chaveCobranca)
// quanto pra casar um caso avulso via IA.
const ExcelJS = require('exceljs');

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}
function linhaTemPreenchimento(cell) {
  const fill = cell && cell.fill;
  if (!fill || fill.type !== 'pattern' || fill.pattern !== 'solid') return false;
  const argb = fill.fgColor && fill.fgColor.argb;
  if (!argb) return false;
  return argb !== 'FFFFFFFF' && argb !== '00000000';
}
async function lerAbaNotas(nodeName, projetoFixo) {
  const item = $(nodeName).first();
  const buffer = Buffer.from(item.binary.data.data, 'base64');
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const ws = wb.getWorksheet('Notas') || wb.worksheets[0];
  const linhas = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return;
    const projetoId = projetoFixo || (linhaTemPreenchimento(row.getCell('L')) ? 'REUNION' : 'AREP');
    linhas.push({
      linha: rowNumber, projetoId,
      colunaB: row.getCell('B').text, colunaC: row.getCell('C').text,
      colunaG: row.getCell('G').text, colunaH: row.getCell('H').text, colunaJ: row.getCell('J').text,
      colunaK: Number(row.getCell('K').value) || 0, colunaL: row.getCell('L').text,
    });
  });
  return linhas;
}

const linhasS01 = await lerAbaNotas('Box — Download Cost Report S01', null);
const linhasS02 = await lerAbaNotas('Box — Download Cost Report S02 (Soft Pré)', 'SOFT_PRE');
const todasAsLinhas = [...linhasS01, ...linhasS02];

const cfg = $('Carregar config + perfis').first().json;

return [{
  json: {
    config: cfg.config, cobrancas: cfg.cobrancas, pendencias: cfg.pendencias, perfis: cfg.perfis,
    dominioEmpresa: cfg.dominioEmpresa,
    roster: todasAsLinhas.map((n) => ({ chave: n.projetoId + '_L' + n.linha, nome: (n.colunaJ.split(' - ')[1] || n.colunaH), fornecedor: n.colunaH, projetoId: n.projetoId, linha: n.linha, codigo: n.colunaB, cargo: n.colunaC, statusBox: n.colunaL })),
  },
}];

// Filtra e-mails com anexo PDF/imagem (ignora os sem anexo relevante), aplica
// limite_linhas_execucao (modo assistido, seção 7.4 — vale pras 3 fases) e
// anexa o contexto (config/roster/etc.) a cada item.
const ctx = $('Parsear planilhas (exceljs) — montar roster').first().json;
const emails = $input.all().filter((item) => {
  const partes = (item.json.payload && item.json.payload.parts) || [];
  return partes.some((p) => p.filename && /\.(pdf|png|jpe?g)$/i.test(p.filename));
});

const limite = ctx.config && ctx.config.limite_linhas_execucao;
const cortados = (!limite || limite <= 0) ? emails : emails.slice(0, limite);

return cortados.map((item) => ({
  json: {
    email: { id: item.json.id, threadId: item.json.threadId, subject: item.json.payload && (item.json.payload.headers || []).find((h) => h.name === 'Subject') && (item.json.payload.headers.find((h) => h.name === 'Subject').value), from: item.json.payload && (item.json.payload.headers || []).find((h) => h.name === 'From') && (item.json.payload.headers.find((h) => h.name === 'From').value) },
    ...ctx,
  },
}));

// Thread conhecida ou avulso? (seção 4) — checagem determinística via threadId
// gravado em cobrancas.json na Fase 1 (seção 3.1.1).
function identificarThreadConhecida(threadIdRecebido, cobrancas) {
  if (!threadIdRecebido || !cobrancas) return { ehConhecida: false };
  const chave = Object.keys(cobrancas).find((k) => cobrancas[k].threadId === threadIdRecebido);
  if (!chave) return { ehConhecida: false };
  return { ehConhecida: true, chaveCobranca: chave, entrada: cobrancas[chave] };
}

return $input.all().map((item) => {
  const d = item.json;
  const resultado = identificarThreadConhecida(d.email.threadId, d.cobrancas);
  return { json: { ...d, ...resultado } };
});

// Interpreta a resposta da IA de extração (nunca lança exceção — regra geral
// de segurança, seção 3.2 item 6 / seção 4: nunca adivinhar).
function parseRespostaIA(t) {
  try { const o = JSON.parse(t); if (!o) return { situacaoNaoMapeada: 'Resposta vazia' }; return o; }
  catch (e) { return { situacaoNaoMapeada: 'Resposta da IA não é JSON válido: ' + String(t).slice(0,300) }; }
}
return $input.all().map((item) => {
  const texto = item.json.content && item.json.content[0] ? item.json.content[0].text : '';
  return { json: { ...item.json, extracao: parseRespostaIA(texto) } };
});

function parseRespostaIA(t) {
  try { const o = JSON.parse(t); if (!o) return { situacaoNaoMapeada: 'Resposta vazia' }; return o; }
  catch (e) { return { situacaoNaoMapeada: 'Resposta da IA não é JSON válido: ' + String(t).slice(0,300) }; }
}
return $input.all().map((item) => {
  const texto = item.json.content && item.json.content[0] ? item.json.content[0].text : '';
  return { json: { ...item.json, match: parseRespostaIA(texto) } };
});

// Sem match confiável (seção 4) — registra pendência e prepara a pergunta
// pro Telegram. NÃO decide nada sozinho.
const d = $input.first().json;
const chave = 'PEND_' + d.email.id;
const pendenciasAtualizadas = { ...(d.pendencias || {}) };
pendenciasAtualizadas[chave] = {
  emailId: d.email.id,
  threadId: d.email.threadId,
  dadosReferencia: d.extracao,
  primeiraPerguntaEm: new Date().toISOString(),
  lembreteEnviado: false,
  resolvida: false,
  mensagemIdOriginal: null, // preenchido depois de enviar a pergunta no Telegram (node seguinte)
};
return [{ json: { ...d, chavePendencia: chave, pendenciasAtualizadas } }];

// Grava mensagemIdOriginal (retornado pelo Telegram) na pendência recém-criada.
const enviado = $input.first().json;
const anterior = $('Registrar pendência de identificação').first().json;
const pendenciasAtualizadas = { ...anterior.pendenciasAtualizadas };
pendenciasAtualizadas[anterior.chavePendencia].mensagemIdOriginal = enviado.message_id || enviado.result?.message_id || null;
return [{ json: {}, binary: { data: { data: Buffer.from(JSON.stringify(pendenciasAtualizadas, null, 2)).toString('base64'), mimeType: 'application/json', fileName: 'pendencias_identificacao.json' } } }];

// Monta o payload pro sub-workflow fase2_finalizar_nota.json — mesmo pra
// thread conhecida (projetoId/linha já sabidos) ou avulso com match confiável.
const d = $input.first().json;

let projetoId, linha, chaveCobranca;
if (d.ehConhecida) {
  chaveCobranca = d.chaveCobranca;
  const partes = chaveCobranca.split('_L');
  // chaveCobranca = perfil.retranca + '_L' + linha — o retranca pode conter '_' também,
  // então pegamos o ÚLTIMO '_L' como separador (linha é sempre numérica no final).
  const m = /_L(\d+)$/.exec(chaveCobranca);
  linha = m ? parseInt(m[1], 10) : null;
  // projetoId: procura no roster pela combinação retranca+linha (roster tem projetoId+linha diretamente).
  const linhaRoster = d.roster.find((r) => r.linha === linha && d.perfis[r.projetoId] && chaveCobranca.startsWith(d.perfis[r.projetoId].retranca));
  projetoId = linhaRoster ? linhaRoster.projetoId : null;
} else {
  const linhaRoster = d.roster.find((r) => r.chave === d.match.linhaEncontrada);
  if (linhaRoster) { projetoId = linhaRoster.projetoId; linha = linhaRoster.linha; }
  chaveCobranca = linhaRoster ? (d.perfis[projetoId].retranca + '_L' + linha) : null;
}

const linhaInfo = d.roster.find((r) => r.projetoId === projetoId && r.linha === linha);

return [{
  json: {
    projetoId, linha, chaveCobranca,
    tipoDocumento: d.extracao.tipoDocumento || 'NF',
    numeroNota: d.extracao.numeroNota || '000000',
    dataEmissao: d.extracao.dataEmissao,
    dataVencimento: linhaInfo ? linhaInfo.colunaG : null,
    razaoSocialOuNome: d.extracao.nomeOuRazaoSocial || (linhaInfo && (linhaInfo.nome || linhaInfo.fornecedor)),
    codigo: linhaInfo ? linhaInfo.codigo : null,
    cargo: linhaInfo ? linhaInfo.cargo : null,
    perfilRetranca: projetoId ? d.perfis[projetoId].retranca : null,
  },
  binary: d.binary,
}];

